-- New Hope Band: migrate all songs into Supabase (run once).
drop table if exists public.songs cascade;
create table public.songs (
  id uuid primary key default gen_random_uuid(),
  title text,
  data jsonb not null,
  created_at timestamptz default now()
);
alter table public.songs enable row level security;
create policy "public read songs" on public.songs for select using (true);
create policy "admin insert songs" on public.songs for insert to authenticated with check (true);
create policy "admin update songs" on public.songs for update to authenticated using (true);
create policy "admin delete songs" on public.songs for delete to authenticated using (true);

